input.command:
mkdir -p .github/workflows && cat > package.json <<'EOF'
{
  "name": "ci-cache-demo",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "test": "node --test"
  }
}
EOF
cat > index.js <<'EOF'
function add(a, b) {
  return a + b;
}

module.exports = { add };
EOF
cat > index.test.js <<'EOF'
const test = require('node:test');
const assert = require('node:assert');
const { add } = require('./index');

test('add', () => {
  assert.strictEqual(add(2, 3), 5);
});
EOF
printf 'node_modules/\n' > .gitignore
npm install --package-lock-only 2>&1 | tail -2 && npm ci && npm test 2>&1 | tail -8

